{
  "headline": "FDA's records trace our supply to a plant classified OAI 962 days before the posting",
  "headline_cites": ["D4"],
  "sentences": [
    {
      "text": "FDA inspection 970483 ended 2016-04-12 and was classified VAI, with the classification letter dated 2016-07-13, which was 962 days before FDA posted the shortage on 2018-11-30.",
      "cites": ["D4"]
    },
    {
      "text": "A prior inspection 876911 ended 2014-03-28 and was classified OAI with six observations including absence of written procedures and deviations from laboratory control requirements.",
      "cites": ["E15"]
    },
    {
      "text": "FDA issued a Warning Letter on 2014-10-21 to the same facility.",
      "cites": ["E21"]
    },
    {
      "text": "Subsequent inspections 940389, 1125050, 1254066, and 1203129 were all classified VAI.",
      "cites": ["E16", "E18", "E19", "E20"]
    },
    {
      "text": "As of 2026-10-21 the shortage has been on FDA's list for 95 months.",
      "cites": ["D9"]
    },
    {
      "text": "Current inventory across Corvale sites ranges from 11 to 23 days on hand.",
      "cites": ["D1", "D2", "D3"]
    },
    {
      "text": "The rule-ranked alternate manufacturer is Samson Medical Technologies, L.L.C., which is not on FDA's shortage list today.",
      "cites": ["D6"]
    }
  ]
}
